solution.solution.cpp:
#include <algorithm>
#include <string>
#include <vector>

int countLongWords(const std::vector<std::string>& words, std::size_t minLength)
{
    const auto count{ std::count_if(words.begin(), words.end(),
        [minLength](const std::string& word) { return word.length() >= minLength; }) };
    return static_cast<int>(count);
}

unitTests:
const std::vector<std::string> sample{ "a", "to", "cat", "tree", "house" };
TEST("at least three letters") { CHECK_EQ(countLongWords(sample, 3), 3); }
TEST("at least one letter is everything") { CHECK_EQ(countLongWords(sample, 1), 5); }
TEST("nothing is that long") { CHECK_EQ(countLongWords(sample, 10), 0); CHECK_EQ(countLongWords({}, 1), 0); }

